//---------------------------------------------------------------------
// name: centroid.ck
// desc: fantastic audio features and where to extract them:
//       extracting spectral centroid; also demonstrates using
//       unit analyzers (UAna), connecting them using the
//       upchuck operator (=^), and getting results
//
// author: Ge Wang (https://ccrma.stanford.edu/~ge/)
// date: Spring 2023
//---------------------------------------------------------------------

// synthesis / analysis network
SinOsc foo => FFT fft =^ Centroid centroid => blackhole;
// set sine frequency
440 => foo.freq;

// set FFT size
1024 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
fft.size()::samp => dur HOP;
// compute srate
second / samp => float srate;

// let one FFT-size of time pass (to buffer)
fft.size()::samp => now;
// control loop
while( true )
{
    //----------------------------------------------------------------
    // upchuck() computes our centroid, automatically computing upstream
    // dependencies connected to it using =^ (e.g., FFT)
    //----------------------------------------------------------------
    centroid.upchuck();

    // get and print the output
    <<< "centroid (hz):", centroid.fval(0) * srate / 2 >>>;

    // advance time
    HOP => now;
}

//---------------------------------------------------------------------
// name: chroma.ck
// desc: chroma unit anlyzer, used for feature extraction of pitch data
//       e.g., a set of frequencies
//
// uncomment for Chroma API:
// Chroma.help();
//
// author: Yikai Li
//         Ge Wang (https://ccrma.stanford.edu/~ge/)
// date: Winter 2023
//---------------------------------------------------------------------

// synthesis / analysis network
SinOsc s => FFT fft =^ Chroma chroma => blackhole;

// set FFT size
2048 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
fft.size()::samp => dur HOP;

// pitch names
["C4", "C#", "D4", "D#", "E4", "F4", "F#", "G4", "G#", "A4", "A#", "B4"] @=> string note_names[];
// test frequencies
[262, 277, 294, 311, 330, 349, 370, 392, 415, 440, 466, 494] @=> int freqs[];

// print header
cherr <= "freq ";
for (0 => int i; i < 12; i++) {
    cherr <= note_names[i] + " ";
}
cherr <= IO.newline();

// let one FFT-size of time pass (to buffer)
fft.size()::samp => now;

// extract chroma features
for( 0 => int i; i < freqs.size(); i++ )
{
    // set frequency for test
    freqs[i] => s.freq;

    //----------------------------------------------------------------
    // upchuck() computes our Chroma, automatically computing upstream
    // dependencies connected to it using =^ (e.g., FFT)
    //----------------------------------------------------------------
    chroma.upchuck();

    // print features
    cherr <= freqs[i] <= ": ";
    for( 0 => int j; j < chroma.fvals().size(); j++ )
    {
        Math.round(chroma.fval(j) * 100) => float tmp;
        cherr <= (tmp < 10 ? " ":"") <= tmp <= " ";
    }
    cherr <= IO.newline();

    // advance time
    HOP => now;
}

//---------------------------------------------------------------------
// name: features-combined.ck
// desc: extracting multiple features; collect into one vector
//       e.g.,  Centroid, Flux, RMS, MFCC
//
// author: Ge Wang (https://ccrma.stanford.edu/~ge/)
// date: Spring 2023
//---------------------------------------------------------------------

// audio input into a FFT
adc => FFT fft;
// a thing for collecting multiple features into one vector
FeatureCollector combo => blackhole;
// add spectral feature: Centroid
fft =^ Centroid centroid =^ combo;
// add spectral feature: Flux
fft =^ Flux flux =^ combo;
// add spectral feature: RMS
fft =^ RMS rms =^ combo;
// add spectral feature: MFCC
fft =^ MFCC mfcc =^ combo;

// set number of coefficients in MFCC (how many we get out)
// 13 is a commonly used value; using less here for printing
13 => mfcc.numCoeffs;
// set number of mel filters in MFCC
10 => mfcc.numFilters;

// set FFT size
2048 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
fft.size()::samp => dur HOP;

// let one FFT-size of time pass (to buffer)
fft.size()::samp => now;
// control loop
while( true )
{
    //-----------------------------------------------------------------
    // a single upchuck() will trigger analysis on everything
    // connected upstream from combo via the upchuck operator (=^)
    // the total number of output dimensions is the sum of
    // dimensions of all the connected unit analyzers
    //-----------------------------------------------------------------
    combo.upchuck();

    // print
    cherr <= "features (" <= combo.fvals().size() <= " total dims): ";
    // print the MFCC results
    for( int i; i < combo.fvals().size(); i++ )
    { cherr <= combo.fval(i) <= " "; }
    // endline
    cherr <= IO.newline();

    // advance time
    HOP => now;
}

// our UGen/UAna patch
adc => FFT fft =^ Flux flux => blackhole;

// set fft size
1024 => fft.size;
// set window (optional here)
Windowing.hann( 1024 ) => fft.window;

// infinite time loop
while( true )
{
    // propogate the analysis computations
    flux.upchuck();
    // print it (should always be 0)
    <<< flux.fval(0) >>>;

    // hop along
    512::samp => now;
}

// our UGen/UAna patch
SinOsc s => FFT fft =^ Flux flux => blackhole;

// compute sample rate
second / samp => float srate;
// set a nice frequency to minimize flux across frames
srate / 8 => s.freq;
// set fft size
1024 => fft.size;
// set window (optional here)
Windowing.hann( 1024 ) => fft.window;

// infinite time loop
while( true )
{
    // propogate the analysis computations (example: optional usage of blob)
    flux.upchuck() @=> UAnaBlob blob;
    // print it (should always be 0)
    <<< blob.fval(0) >>>;

    // hop along
    512::samp => now;
}

