//---------------------------------------------------------------------
// name: mfcc-mean.ck
// desc: mel-frequency cepstral coefficients
//       this example aggregates multiple MFCC frames; compute mean
//
// version: need chuck version 1.5.0.0 or higher
// sorting: part of ChAI (ChucK for AI)
//
// to see API, uncomment:
// MFCC.help();
//
// author: Yikai Li and Ge Wang
// date: Spring 2023
//---------------------------------------------------------------------

// analysis patch
adc => FFT fft =^ MFCC mfcc => blackhole;

// FFT size
2048 => fft.size;
// FFT hop size
512 => int hopSize;
// number of filters in MEL space
10 => mfcc.numFilters;
// number of MFCC coefficients to compute per frame
13 => mfcc.numCoeffs => int nCoeffs;
// used to compute the frame size
.1::second => dur aggregateTime;
// set FFT window
Windowing.hamming(fft.size()) => fft.window;
// current sample sample
second / samp => float sampleRate;
// this should already be set to the current chuck srate
// but could be overridden, if desired
// sampleRate => mfcc.sampleRate;

// calculate the number of frames
(aggregateTime/second * sampleRate / hopSize + .5) $ int => int nFrames;

// print out
chout <= IO.newline();
<<< "--------------------------------------------", "" >>>;
<<< "num filters:", mfcc.numFilters() >>>;
<<< "num MFCC coefficients:", mfcc.numCoeffs() >>>;
<<< "agregrateTime:", aggregateTime/second, "seconds" >>>;
<<< "num frames:", nFrames >>>;
<<< "--------------------------------------------", "" >>>;
chout <= IO.newline();

// per-frame MFCC coefficients
float mfccs[nFrames][nCoeffs];
// average of MFCC coefficients across all frames
float mfccMean [nCoeffs];

// let one FFTsize of time pass
fft.size()::samp => now;

// analysis loop
while( true )
{
    // aggregate mfcc features
    for( 0 => int fi; fi < nFrames; fi++ )
    {
        // triggers MFCC and its dependencies (e.g., FFT)
        mfcc.upchuck();
        // get contents
        for( 0 => int i; i < nCoeffs; i++ )
        {
            // copy the resulting coeffs
            mfcc.fval(i) => mfccs[fi][i];
        }
        // advance time by one hop
        hopSize::samp => now;
    }

    // compute mean
    for( 0 => int i; i < nCoeffs; i++ )
    {
        // zero out
        0.0 => mfccMean[i];
        // sum
        for (0 => int j; j < nFrames; j++)
        {
            mfccs[j][i] +=> mfccMean[i];
        }
        // divide by frames
        nFrames /=> mfccMean[i];
        // print
        chout <= mfccMean[i] <= " ";
    }

    // new line
    chout <= IO.newline();
}

// our patch
adc => FFT fft =^ RMS rms => blackhole;

// set parameters
1024 => fft.size;
// set hann window
Windowing.hann(1024) => fft.window;

// control loop
while( true )
{
    // upchuck: take fft then rms
    rms.upchuck() @=> UAnaBlob blob;
    // print out RMS
    <<< blob.fval(0) >>>;

    // advance time
    fft.size()::samp => now;
}

// our patch
adc => FFT fft =^ RollOff roff50 => blackhole;
// a second rolloff
fft =^ RollOff roff85 => blackhole;

// set parameters
1024 => fft.size;
// set hann window
Windowing.hann(1024) => fft.window;
// compute srate
second / samp => float srate;
// set rolloff percents
.5 => roff50.percent;
.85 => roff85.percent;

// control loop
while( true )
{
    // upchuck: take fft then the rolloffs
    roff50.upchuck();
    roff85.upchuck();
    // print out
    <<< "50% rolloff:", roff50.fval(0) * srate / 2,
        "85% rolloff:", roff85.fval(0) * srate / 2 >>>;

    // advance time
    fft.size()::samp => now;
}

// our patch
adc => FFT fft =^ RollOff roff50 => blackhole;
// a second rolloff
fft =^ RollOff roff85 => blackhole;

// set parameters
1024 => fft.size;
// set hann window
Windowing.hann(1024) => fft.window;
// compute srate
second / samp => float srate;
// set rolloff percents
.5 => roff50.percent;
.85 => roff85.percent;

// control loop
UAnaBlob blobby;
UAnaBlob blobert;
while( true )
{
    // upchuck: take fft then the rolloffs
    roff50.upchuck() @=> blobby;
    roff85.upchuck() @=> blobert;
    // print out
    <<< "50% rolloff:", blobby.fvals()[0] * srate / 2,
        "85% rolloff:", blobert.fvals()[0] * srate / 2 >>>;

    // advance time
    fft.size()::samp => now;
}

//---------------------------------------------------------------------
// name: sfm.ck
// desc: Spectral Flatness Measure
//
// uncomment for SFM API:
// SFM.help();
//
// author: Yikai Li
//         Ge Wang
// date: Winter 2023
//---------------------------------------------------------------------

// synthesis / analysis network
SinOsc s => FFT fft =^ SFM sfm => blackhole;

// set FFT size
2048 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
fft.size()::samp => dur HOP;

// let one FFT-size of time pass (to buffer)
fft.size()::samp => now;
// control loop
while( true )
{
    //----------------------------------------------------------------
    // upchuck() computes SFM, automatically computing upstream
    // dependencies connected to it using =^ (e.g., FFT)
    //----------------------------------------------------------------
    sfm.upchuck();
    // print
    cherr <= "SFM: ";
    // print the SFM results
    for( int i; i < sfm.fvals().size(); i++ )
    {
        Math.round(sfm.fval(i) * 10) / 10 => float tmp;
        cherr <= tmp <= (tmp == 1 || tmp == 0?".0":"") <= " ";
    }
    // endline
    cherr <= IO.newline();
    // advance time
    HOP => now;
    // randomize frequency
    Math.random2f(20, 1000) => s.freq;
}

//----------------------------------------------------------------
// name: ZeroX (Zero Crossing Detector)
// desc: Detect the number of zero crosses in a Flip of samples
//       1. Flip will convert N samples to a UAna Frame
//       2. ZeroX will then count the number of zero crossings in 
//       the UAna Frame 
//       
//       Note the ZeroX output in this example is equal to
//       zeroX = 2*freq / (sample_rate / N) 
//----------------------------------------------------------------

// analysis patch
SinOsc foo => Flip flip =^ ZeroX zerox => blackhole;

// set flip size (N)
4096 => flip.size;

// change the frequency of foo randomly every 1-2 seconds
fun void ctrl()
{
    while( true )
    {
        // new random freq
        Math.random2f( 100, 2000 ) => foo.freq;
        <<< "setting new freq:", foo.freq() >>>;
        // wait 1-2 seconds
        Math.random2f( 1, 2 )::second => now;
    }
}

// spork frequency changer shred
spork ~ ctrl();

// main
while( true )
{
    // compute ZeroX in the last UAna Frame
    // store the result in a UAnaBlob
    zerox.upchuck() @=> UAnaBlob blob;

    // print number of zero crossings
    <<< blob.fvals()[0], "" >>>;

    // advance time
    flip.size()::samp => now;
}

//---------------------------------------------------------------------
// name: feature-extract.ck
// desc: sets up automated extraction over a training dataset
//       this example can be adapted to other labeled audio dataset
//
// version: need chuck version 1.5.0.0 or higher
// sorting: part of ChAI (ChucK for AI)
//
// DATA: by default, this uses the GTZAN dataset:
//       download and unzip updated version:
//       https://chuck.stanford.edu/chai/data/gtzan/
//
// USAGE: this is purely for feature extraction on training data, so...
//        run chuck in non-real-time mode (this actually can be much
//        faster than real-time mode, since it doesn't synch to audio):
//
//        extract and print
//            > chuck --silent 2-extract.ck
//
//        extract and write to FILE
//            > chuck --silent 2-extract.ck:FILE
//
// date: Spring 2023
// authors: Ge Wang (https://ccrma.stanford.edu/~ge/)
//          Yikai Li
//---------------------------------------------------------------------


// output file (if empty, will print to console)
"" => string OUTPUT_FILE;
// get from arguments
if( me.args() > 0 ) me.arg(0) => OUTPUT_FILE;

// check
if( Machine.silent() == false )
{
    // print helpful message
    <<< "-----------------", "" >>>;
    <<< "[feature-extract]: chuck is currently running in REAL-TIME mode;", "" >>>;
    <<< "[feature-extract]: this step has no audio; may run much faster in SILENT mode!", "" >>>;
    <<< "[feature-extract]: to run in SILENT mode, restart chuck with --silent flag", "" >>>;
    <<< "-----------------", "" >>>;
}


//---------------------------------------------------------------------
// analysis network -- this determines which feature will be extracted
//---------------------------------------------------------------------
// audio input into a FFT
SndBuf audioFile => FFT fft;
// a thing for collecting multiple features into one vector
FeatureCollector combo => blackhole;
// add spectral feature: Centroid
fft =^ Centroid centroid =^ combo;
// add spectral feature: Flux
fft =^ Flux flux =^ combo;
// add spectral feature: RMS
fft =^ RMS rms =^ combo;
// add spectral feature: MFCC
fft =^ MFCC mfcc =^ combo;


//---------------------------------------------------------------------
// setting analysis parameters -- important for tuning your extraction
//---------------------------------------------------------------------
// set number of coefficients in MFCC (how many we get out)
// 13 is a commonly used value; using less here for printing
20 => mfcc.numCoeffs;
// set number of mel filters in MFCC
10 => mfcc.numFilters;

// do one .upchuck() so FeatureCollector knows how many total dimension
combo.upchuck();
// get number of total feature dimensions
combo.fvals().size() => int NUM_DIMENSIONS;

// set FFT size
2048 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
2048::samp => dur HOP;


//---------------------------------------------------------------------
// training data -- preparation specific to a train dataset
//---------------------------------------------------------------------
// labels (and filename roots)
["blues", "classical", "country", "disco", "hiphop",
 "jazz", "metal", "pop", "reggae", "rock"] @=> string labels[];
// how many per label
100 => int NUM_EXAMPLES_PER_LABEL;
// how much time to aggregate features for each file
10::second => dur EXTRACT_TIME;
// given EXTRACT_TIME and HOP, how many frames per file?
(EXTRACT_TIME / HOP) $ int => int numFrames;
// relative path
"data/gtzan/genres_original/" => string PATH;

// a feature frame
float featureFrame[NUM_DIMENSIONS];
// how many input files
0 => int NUM_FILES;

// output reference, default is error stream (cherr)
cherr @=> IO @ theOut;
// instantiate
FileIO fout;
// output file
if( OUTPUT_FILE != "" )
{
    // print
    <<< "opening file for output:", OUTPUT_FILE >>>;
    // open
    fout.open( OUTPUT_FILE, FileIO.WRITE );
    // test
    if( !fout.good() )
    {
        <<< "cannot open file for writing...", "" >>>;
        me.exit();
    }
    // override
    fout @=> theOut;
}


//---------------------------------------------------------------------
// extraction -- iterating over entire training dataset
//---------------------------------------------------------------------

// filename
string filename;
// loop over labels
for( int i; i < labels.cap(); i++)
{
    // get current label
    labels[i] => string label;
    // loop over examples under each label
    for( int j; j < NUM_EXAMPLES_PER_LABEL; j++ )
    {
        // construct filepath
        me.dir() + PATH + label + "/" + label + ".000" + (j<10?"0":"") + j + ".wav" => filename;
        // extract the file
        if( !extractFeatures( filename, label, theOut ) )
        {
            // issue warning
            cherr <= "PROBLEM during extraction: " <= filename <= IO.newline();
            // bail out
            me.exit();
        }
    }
}


//---------------------------------------------------------------------
// function: extract and print features from a single file
//---------------------------------------------------------------------
fun int extractFeatures( string inputFilePath, string label, IO out )
{    
    // increment
    NUM_FILES++;
    // log 
    cherr <= "[" <= NUM_FILES <= "] extracting features: " <= inputFilePath <= IO.newline();

    // load by block to speed up IO
    2048 => audioFile.chunks;
    // read the audio file
    inputFilePath => audioFile.read;
    // zero out
    featureFrame.zero();

    // let one FFT-size of time pass (to buffer)
    fft.size()::samp => now;
    // loop over frames
    for( int i; i < numFrames; i++ )
    {
        //-------------------------------------------------------------
        // a single upchuck() will trigger analysis on everything
        // connected upstream from combo via the upchuck operator (=^)
        // the total number of output dimensions is the sum of
        // dimensions of all the connected unit analyzers
        //-------------------------------------------------------------
        combo.upchuck();
        // for each dimension
        for( int d; d < NUM_DIMENSIONS; d++ )
        {
            // copy
            combo.fval(d) +=> featureFrame[d];
        }
        // advance time
        HOP => now;
    }

    //-------------------------------------------------------------
    // average into a single feature vector per file
    // NOTE: this can be easily modified to N feature vectors
    // spread out over the length of an audio file; for now
    // we will just do one feature vector per file
    //-------------------------------------------------------------
    for( int d; d < NUM_DIMENSIONS; d++ )
    {
        // average by total number of frames
        numFrames /=> featureFrame[d];
        // print the MFCC results
        out <= featureFrame[d] <= " ";
    }    
    // print label name and endline
    out <= label <= IO.newline();

    // done
    return true;
}

//------------------------------------------------------------------------------
// name: genre-classify.ck
// desc: a real-time genre-classifier using the features extracted using
//       GTZAN dataset + features-extract.ck
//
// version: need chuck version 1.5.0.0 or higher
// sorting: part of ChAI (ChucK for AI)
//
// USAGE: run in any real-time mode (default)
//        > chuck classify-genres.ck
//
// uncomment the next line to learn more about the KNN2 object:
// KNN2.help();
//
// date: Spring 2023
// authors: Ge Wang (https://ccrma.stanford.edu/~ge/)
//          Yikai Li
//------------------------------------------------------------------------------

// input: pre-extracted features file with labels
me.dir() + "data/gtzan-23.txt" => string FEATURES_FILE;
// if have arguments, override filename
if( me.args() > 0 ) me.arg(0) => FEATURES_FILE;
//------------------------------------------------------------------------------
// expected features file format:
//------------------------------------------------------------------------------
// VALUE VALUE ... VALUE LABEL
// VALUE VALUE ... VALUE LABEL
// ...   ...   ... ...   LABEL
// VALUE VALUE ... VALUE LABEL
//------------------------------------------------------------------------------


//------------------------------------------------------------------------------
// unit analyzer network: this must match the features in the features file
//------------------------------------------------------------------------------
// audio input into a FFT
adc => FFT fft;
// a thing for collecting multiple features into one vector
FeatureCollector combo => blackhole;
// add spectral feature: Centroid
fft =^ Centroid centroid =^ combo;
// add spectral feature: Flux
fft =^ Flux flux =^ combo;
// add spectral feature: RMS
fft =^ RMS rms =^ combo;
// add spectral feature: MFCC
fft =^ MFCC mfcc =^ combo;


//-----------------------------------------------------------------------------
// setting analysis parameters -- also should match what was used during extration
//-----------------------------------------------------------------------------
// set number of coefficients in MFCC (how many we get out)
// 13 is a commonly used value; using less here for printing
20 => mfcc.numCoeffs;
// set number of mel filters in MFCC
10 => mfcc.numFilters;

// do one .upchuck() so FeatureCollector knows how many total dimension
combo.upchuck();
// get number of total feature dimensions
combo.fvals().size() => int NUM_DIMENSIONS;

// set FFT size
2048 => fft.size;
// set window type and size
Windowing.hann(fft.size()) => fft.window;
// our hop size (how often to perform analysis)
2048::samp => dur HOP;


//------------------------------------------------------------------------------
// load feature data; read important global values like numPoints and numCoeffs
//------------------------------------------------------------------------------
// values to be read from file
0 => int numPoints; // number of points in data
0 => int numCoeffs; // number of dimensions in data
// file read PART 1: read over the file to get numPoints and numCoeffs
loadFile( FEATURES_FILE ) @=> FileIO @ fin;
// check
if( !fin.good() ) me.exit();
// check dimension
if( numCoeffs != NUM_DIMENSIONS )
{
    // error
    <<< "[error] expecting:", NUM_DIMENSIONS, "dimensions; but features file has:", numCoeffs >>>;
    // stop
    me.exit();
}

// labels of all data points
string inLabels[numPoints];
// label indices of all data points
int inLabelsInt[inLabels.size()];
// feature vectors of data points
float inFeatures[numPoints][numCoeffs];
// keys
string labels[0];
// use as map: labels to numbers
int label2int[0];

//------------------------------------------------------------------------------
// array for storing features
//------------------------------------------------------------------------------
// how much time to aggregate features for each file
// (this does not need to match extraction; might play with this number)
.5::second => dur EXTRACT_TIME;
// given EXTRACT_TIME and HOP, how many frames per file?
(EXTRACT_TIME / HOP) $ int => int numFrames;

// use this for new input
float features[numFrames][numCoeffs];
// average values of coefficients across frames
float featureMean[numCoeffs];
// for printing
int lengths[0];
// for printing (how much to indent)
int indents[0];


//------------------------------------------------------------------------------
// read the data
//------------------------------------------------------------------------------
readData( fin );


//------------------------------------------------------------------------------
// set up our KNN object to use for classification
// (KNN2 is a fancier version of the KNN object)
// -- run KNN2.help(); in a separate program to see its available functions --
//------------------------------------------------------------------------------
KNN2 knn;
// k nearest neighbors
10 => int K;
// results vector
float knnResult[labels.size()];
// knn train
knn.train( inFeatures, inLabelsInt );




//------------------------------------------------------------------------------
// real-time classification loop
//------------------------------------------------------------------------------
while( true )
{
    // aggregate features over a period of time
    for( int frame; frame < numFrames; frame++ )
    {
        //-------------------------------------------------------------
        // a single upchuck() will trigger analysis on everything
        // connected upstream from combo via the upchuck operator (=^)
        // the total number of output dimensions is the sum of
        // dimensions of all the connected unit analyzers
        //-------------------------------------------------------------
        combo.upchuck();  
        // get features
        for( int d; d < NUM_DIMENSIONS; d++) 
        {
            // store them in current frame
            combo.fval(d) => features[frame][d];
        }
        // advance time
        HOP => now;
    }

    // compute means for each coefficient across frames
    for( int d; d < NUM_DIMENSIONS; d++ )
    {
        // zero out
        0.0 => featureMean[d];
        // loop over frames
        for( int j; j < numFrames; j++ )
        {
            // add
            features[j][d] +=> featureMean[d];
        }
        // average
        numFrames /=> featureMean[d];
    }

    //-------------------------------------------------
    // predict using KNN2; results filled in knnResults
    //-------------------------------------------------
    knn.predict( featureMean, K, knnResult );

    // print results
    chout <= "-------------------------------------------------" <= IO.newline();
    // print for each label
    for( int i; i < knnResult.size(); i++ )
    {
        // print label
        chout <= labels[i] <= ":";
        // print indentatation
        for( int ii; ii < indents[i]; ii++ ) { chout <= " "; }
        // print probability
        chout <= knnResult[i] <= IO.newline();
    }
}
//------------------------------------------------------------------------------
// end of real-time classification loop
//------------------------------------------------------------------------------




//------------------------------------------------------------------------------
// function: load data file
//------------------------------------------------------------------------------
fun FileIO loadFile( string filepath )
{
    // reset
    0 => numPoints;
    0 => numCoeffs;

    // load data
    FileIO fio;
    if( !fio.open( filepath, FileIO.READ ) )
    {
        // error
        <<< "cannot open file:", filepath >>>;
        // close
        fio.close();
        // return
        return fio;
    }

    string str;
    string line;
    // read file int array
    while( fio.more() )
    {
        // read each line
        fio.readLine().trim() => str;
        // check if empty line
        if( str != "" )
        {
            numPoints++;
            str => line;
        }
    }

    // a string tokenizer
    StringTokenizer tokenizer;
    // set to last non-empty line
    tokenizer.set( line );
    // -1 (to account for label)
    -1 => numCoeffs;
    // see how many, including label name
    while( tokenizer.more() )
    {
        tokenizer.next();
        numCoeffs++;
    }

    // check
    if( numPoints == 0 || numCoeffs <= 0 )
    {
        <<< "no data in file:", filepath >>>;
        fio.close();
        return fio;
    }

    // print
    <<< "# of data points:", numPoints, "dimensions:", numCoeffs >>>;

    // done for now
    return fio;
}


//------------------------------------------------------------------------------
// function: read the data
//------------------------------------------------------------------------------
fun void readData( FileIO fio )
{
    // rewind the file reader
    fio.seek( 0 );

    // read file int array
    string str;
    int ci, ri;
    while( fio => str )
    {
        // check for last
        if( (ci != 0) && ((ci % numCoeffs) == 0) )
        {
            // read in label
            str => inLabels[ri];
            // set in map
            1 => label2int[str];
            // increment row
            ri++;
            // reset column
            0 => ci;
        }
        else
        {
            // store feature value
            Std.atof(str) => inFeatures[ri][ci];
            // increment column
            ci++;
        }
    }

    // get keys from map
    label2int.getKeys( labels );
    // assign index
    for( int i; i < labels.size(); i++ )
    { i => label2int[labels[i]]; }
    // convert in labels to ints
    for( int i; i < inLabels.size(); i++ )
    {
        // get index as int
        label2int[inLabels[i]] => inLabelsInt[i];
    }

    // max length
    0 => int maxLength;
    // get lengths of label names for printing
    for( int i; i < labels.size(); i++ )
    {
        // compare with max length
        if( labels[i].length() > maxLength )
            labels[i].length() => maxLength;
        // append to array
        lengths << labels[i].length();
    }

    // get lengths of label names for printing
    for( int i; i < lengths.size(); i++ )
    {
        // get indent for length
        indents << (maxLength + 1 ) - lengths[i];
    }
}

//------------------------------------------------------------------------------
// name: x-validate.ck
// desc: a cross validation example using extracted features
//
// version: need chuck version 1.5.0.0 or higher
// sorting: part of ChAI (ChucK for AI)
//
// USAGE: this is purely for cross validation on extracted features, so ...
//        run chuck in non-real-time mode (this actually can be much
//        faster than real-time mode, since it doesn't synch to audio):
//
//        cross validation from FILE
//            > chuck --silent x-validate.ck:FILE
//
// date: Spring 2023
// authors: Yikai Li
//          Ge Wang (https://ccrma.stanford.edu/~ge/)
//------------------------------------------------------------------------------

// input: pre-extracted features file with labels
"" => string FEATURES_FILE;
// if have arguments, override filename
if( me.args() > 0 ) me.arg(0) => FEATURES_FILE;
else
{ <<< "[usage]: chuck --silent x-validate:FILE", "" >>>; me.exit();}
//------------------------------------------------------------------------------
// expected features file format:
//------------------------------------------------------------------------------
// VALUE VALUE ... VALUE LABEL
// VALUE VALUE ... VALUE LABEL
// ...   ...   ... ...   LABEL
// VALUE VALUE ... VALUE LABEL
//------------------------------------------------------------------------------


//------------------------------------------------------------------------------
// load feature data; read important global values like numPoints and numCoeffs
//------------------------------------------------------------------------------
// values to be read from file
0 => int numPoints; // number of points in data
0 => int numCoeffs; // number of dimensions in data
// file read PART 1: read over the file to get numPoints and numCoeffs
loadFile( FEATURES_FILE ) @=> FileIO @ fin;
// check
if( !fin.good() ) me.exit();

// labels of all data points
string inLabels[numPoints];
// label indices of all data points
int inLabelsInt[inLabels.size()];
// feature vectors of data points
float inFeatures[numPoints][numCoeffs];
// keys
string labels[0];
// use as map: labels to numbers
int label2int[0];


//------------------------------------------------------------------------------
// read the data
//------------------------------------------------------------------------------
readData( fin );


//------------------------------------------------------------------------------
// set up our KNN object to use for classification
// (KNN2 is a fancier version of the KNN object)
// -- run KNN2.help(); in a separate program to see its available functions --
//------------------------------------------------------------------------------
KNN2 knn;
// k nearest neighbors
10 => int K;
// results vector
float knnResult[labels.size()];


//------------------------------------------------------------------------------
// cross validation
//------------------------------------------------------------------------------
// number of folds
20 => int numFolds;
// number of folds to use for testing
4 => int numTestFolds;
// number of folds to use for training
numFolds - numTestFolds => int numTrainFolds;
// number of points in each fold
(numPoints / numFolds) $ int => int numPointsPerFold;
// feature vectors of training data
float trainFeatures[numTrainFolds * numPointsPerFold][numCoeffs];
// labels of training data
int trainLabelsInt[numTrainFolds * numPointsPerFold];
// feature vectors of testing data
float testFeatures[numTestFolds * numPointsPerFold][numCoeffs];
// labels of testing data
int testLabelsInt[numTestFolds * numPointsPerFold];
// normalize the data
normalizeData();
// shuffle the data
shuffleData();
// cross validation
for( 0 => int i; i < numFolds / numTestFolds; i++)
{
    // prepare training and testing data
    prepareData( i );
    // train
    knn.train( trainFeatures, trainLabelsInt );
    // test
    0.0 => float accuracy;
    for( 0 => int j; j < testLabelsInt.size(); j++ )
    {
        // predict
        knn.predict( testFeatures[j], K, knnResult );
        // aggregate accuracy
        knnResult[ testLabelsInt[j] ] +=> accuracy;
    }
    // print accuracy
    chout <= "fold " + i + " accuracy: " + ( accuracy / testLabelsInt.size() ) <= IO.newline();
}


//------------------------------------------------------------------------------
// function: normalizeData()
//------------------------------------------------------------------------------
fun void normalizeData()
{
    // for each dimension
    for( 0 => int i; i < numCoeffs; i++ )
    {
        // find min and max
        inFeatures[0][i] => float min;
        inFeatures[0][i] => float max;
        for( 1 => int j; j < numPoints; j++ )
        {
            if( inFeatures[j][i] < min ) inFeatures[j][i] => min;
            if( inFeatures[j][i] > max ) inFeatures[j][i] => max;
        }
        max - min => float range;
        // normalize
        for( 0 => int j; j < numPoints; j++ )
            (inFeatures[j][i] - min) / range => inFeatures[j][i];
    }
}


//------------------------------------------------------------------------------
// function: shuffleData()
//------------------------------------------------------------------------------
fun void shuffleData()
{
    // prepare swap data
    float swapFeatures[numCoeffs];
    int swapLabelInt;
    // shuffle the data
    for( numPoints - 1 => int i; i > 0; i-- )
    {
        // random index
        Math.random2( 0, i ) => int j;
        // swap features
        for( 0 => int k; k < numCoeffs; k++ )
        {
            inFeatures[i][k] => swapFeatures[k];
            inFeatures[j][k] => inFeatures[i][k];
            swapFeatures[k] => inFeatures[j][k];
        }
        // swap labels
        inLabelsInt[i] => swapLabelInt;
        inLabelsInt[j] => inLabelsInt[i];
        swapLabelInt => inLabelsInt[j];
    }
}


//------------------------------------------------------------------------------
// function: prepareData( int fold )
//------------------------------------------------------------------------------
fun void prepareData( int fold )
{
    // test indices
    fold * numTestFolds * numPointsPerFold => int testStart;
    testStart + numTestFolds * numPointsPerFold => int testEnd;
    // index
    0 => int train_i;
    0 => int test_i;
    // prepare training and testing data
    for( 0 => int i; i < numPoints; i++ )
    {
        // test
        if( i >= testStart && i < testEnd )
        {
            // copy features
            for( 0 => int j; j < numCoeffs; j++ )
                inFeatures[i][j] => testFeatures[test_i][j];
            // copy label
            inLabelsInt[i] => testLabelsInt[test_i];
            // increment
            test_i++;
        }
        // train
        else
        {
            // copy features
            for( 0 => int j; j < numCoeffs; j++ )
                inFeatures[i][j] => trainFeatures[train_i][j];
            // copy label
            inLabelsInt[i] => trainLabelsInt[train_i];
            // increment
            train_i++;
        }
    }
}


