//--------------------------------------------------------
// name: paulstretch.ck
// desc: Paul's Extreme Sound Stretch (Paulstretch) 
//       (requires: chuck-1.5.5.6 or higher)
//
// author: Celeste Betancur Gutierrez
//         adapted from Paul Nasca's Python implementation
// date: Fall 2025
//--------------------------------------------------------

//--------------------------------------------------------
// this is the stretch factor
// e.g., .05 is 20x time-stretch
// 1 is normal/no stretch
// 0 is freeze
.05 => float resolution;
//--------------------------------------------------------
// FFT window size
// larger == better quality but more bursty CPU load
4096*4 => int windowSize;

// ensure even window size
(windowSize / 2) * 2 => windowSize;
windowSize / 2 => int halfWindowSize;

// preview
SndBuf input => dac;
// feel free to use your own sample here
"special:dope" => input.read;
// print
cherr <= "DOH" <= IO.nl();
// play it without stretching
input.length() => now;
// disconnect preview patch
input =< dac;
// wait a bit
.5::second => now;

// audio analysis
input => FFT fft => blackhole;
// playhead
0 => input.pos;
// loop it
1 => input.loop;


// audio synthesis
IFFT ifft1 => Gain output => dac;
IFFT ifft2 => output => dac;

// set window size
windowSize => fft.size => ifft1.size => ifft2.size;

// Hann window to have a nice Overlap-add :)
(halfWindowSize/2) => int overlapAdd;
Windowing.hann(windowSize) => fft.window => ifft1.window => ifft2.window;
// complex frequency bins
complex freqBuffer[halfWindowSize];
// compute playback hop size
(overlapAdd * (input.sampleRate()) / (second/samp)$float)$int => int playbackHop;

// shred for randomize phase
fun void randomizePhase()
{
    while( true )
    {
        // trigger ananlysis up the UAna chain from fft
        fft.upchuck();

        // iterate over frequency bins
        for (int i; i < halfWindowSize; i++)
        {
            // compute magnitude
            (fft.cval(i)$polar).mag => float mag;
            // generate random phase
            Math.random2f(-Math.PI, Math.PI) => float randomPhase;
            // reconstruct with random phase
            #(mag * Math.cos(randomPhase), mag * Math.sin(randomPhase)) => freqBuffer[i];
        }
        // advance time by overlap-add duration
        overlapAdd::samp => now;

        // return the playhead by resolution factor
        (input.pos()) - ((playbackHop - playbackHop*(resolution))$int) => input.pos;
    }
}

// shred for reconstructing the audio
fun void reconstruct()
{
    while( true )
    {
        // overlap-add
        ifft1.transform( freqBuffer );
        overlapAdd::samp => now;
        ifft2.transform( freqBuffer );
        overlapAdd::samp => now;
    }
}

fun void transcribe()
{
    100::ms => dur T;
    while( true )
    {
        // the beginning
        if( input.pos() < 5 ) cherr <= "D";
        // this does not work as intended but works in effect
        else if( input.samples() - input.pos() < T/samp ) cherr <= "H";
        else cherr <= "O";
        T => now;
    }
}

// go
spork~randomizePhase();
spork~reconstruct();
spork~transcribe();

// advance time
while( true ) 1::second => now;

////////////////////////////////////////////////////////////////////
// PitchTrack is a monophonic autocorrelation pitch tracker with  //
// a fast response and extremely high accuracy, even at low       //
// frequencies. It is adapted from [helmholtz~] for Pd by Katja,  //
// documented at http://www.katjaas.nl/helmholtz/helmholtz.html   //
////////////////////////////////////////////////////////////////////

// Options
// get(): (read only) get calculated frequency
//
// fidelity: (float) [0-1], default 0.95
//   This is a threshold for certainty about the result. A highly periodic
//   signal (ie one that has a strong pitch center) should produce a result
//   with a high fidelity, which a non-periodic signal (eg noise) will have
//   a very low fidelity. Setting this parameter close to 1 should reduce
//   the number of inaccurate reports.
//
// sensitivity (float) [0-1], default 0.003
//   This is the minimum RMS value to trigger a pitch calculation. Setting
//   this parameter low forces PitchTrack to attempt to find the pitch of
//   even very quiet sounds. Higher values will cause it to trigger only
//   on louder notes.
//
// overlap (int) [1-?], default 2
//   How much to overlap successive analysis frames. Higher values should
//   produce smoother values, at the cost of an increase of CPU load.
//
// frame (int) [128-?], default 2048
//   Size of FFT frame for analysis. Smaller values result in lower latency
//   and high responsiveness but less accuracy. Higher values result in
//   considerably greater CPU load. Values that aren't powers of 2 get
//   rounded up to the next power of 2. Recommend 512, 1024, or 2048.
//
// bias (float) [0-1], default 0.2
//   Katja's pitch tracker introduces a small bias to help with the tracking.
//   (See the link above.) I don't know how this parameter affects the output.

// Example
SinOsc osc => dac; // create an oscillator
// PitchTrack must connect to blackhole to run
osc => PitchTrack pitch => blackhole;

0.5 => osc.gain;

while (true)
{
	// set the oscillator to a random frequency
	Math.random2f(200,1000) => osc.freq;
	<<< "Actual oscillator frequency:",osc.freq(),"Hz" >>>;
	250::ms => now; // pass a little time
	<<< "PitchTrack thinks it's this:",pitch.get(),"Hz" >>>;
	<<< "Difference:",Math.fabs(osc.freq() - pitch.get()),"Hz\n" >>>;
	2::second => now;
}

///////////////////////////////////////////////////
// Sigmund: sinusoidal analysis & pitch tracking //
//                                               //
// by Miller Puckette                            //
//                                               //
///////////////////////////////////////////////////

// Options:
// npts (int): number of points used in analysis.
//     Must be a power of 2, at least 128. The
//     minimum frequency that can be tracked is
//     about 2 * samplerate / npts
//     default: 1024
//
// npeak (int): maximum number of sinusoidal peaks
//     to look for. The computation time is
//     quadratic in the number of peaks actually
//     found (this number only sets an upper
//     limit). Use it to balance CPU time with
//     quality of results.
//
// maxfreq (float): maximum frequency of sinusoidal
//     peaks to look for. This can be useful in
//     situations where background nose creates
//     high-frequency, spurious peaks...
//
// minpower (float): minimum dB level to
//     report a pitch. Signals quieter than this
//     will be assumed to be crosstalk and ignored.
//     default: 50
//
// freq() (read-only): get reported frequency of
//     input signal
//
// env() (read-only): get reported RMS value (in dB)
//     of input signal
//
// peak (int): report freq of nth sinusoundal peak
//     sorting depends on parameter "dotracks"
//
// amp (int): report amplitude of nth sinusoundal peak
//     sorting depends on parameter "dotracks"
//
// tracks (0/1): toggle whether peak and amp are
//     sorted in order of amplitude or organized into
//     tracks
//
// clear(): clear buffers and reset
//
// param1, param2, param3 (float): mysterious settings...

// must connect to blackhole to perform DSP
TriOsc foo => Sigmund siggy => blackhole;

4096 => siggy.npts;
20 => siggy.npeak;
1000 => siggy.maxfreq;
25 => siggy.minpower;

while (true)
{
	Math.random2f(5,300) => foo.freq;
	Math.random2f(0,1) => foo.gain;
	second => now;
	<<< "Real frequency:",foo.freq(),"real gain:",foo.gain(),"Sigmund found this:",siggy.freq(), "power:", siggy.env() >>>;
}

//--
// name: harm.ck
// desc: using Tracking and Smacking to harmonize
//
// author: Rebecca Fiebrink + Ge Wang
// date: 2007
//--


// synthesis
BlitSaw s => JCRev r => dac;
4 => s.harmonics;

// set reverb mix
.05 => r.mix;
// possible hamonizing intervals
[ 3-24, 4-12, 7, 9+12 ] @=> int harms[];
float the_harm;

// interpolate
float target_freq, curr_freq, target_gain, curr_gain;
spork ~ ramp_stuff();
spork ~ smack_handler();

// go for it
while( true )
{
    // wait for analysis event
    Tracking.the_event => now;

    // set freq
    Tracking.the_freq * Math.pow(1.059, the_harm) => target_freq;
    // set gain
    Tracking.the_gain => target_gain;
}

// interpolation
fun void ramp_stuff()
{
    // mysterious 'slew'
    0.025 => float slew;

    // infinite time loop
    while( true )
    {
        (target_freq - curr_freq) * 1 * slew + curr_freq => curr_freq => s.freq;
        (target_gain - curr_gain) * .25 * slew + curr_gain => curr_gain => s.gain;
        0.0025::second => now;
    }
}

// handles smack
fun void smack_handler()
{
    // go
    while( true )
    {
        // wait
        Smacking.the_event => now;

        // choose random interval
        harms[Math.random2(0,harms.size()-1)] => the_harm;
        // set freq
        Tracking.the_freq * Math.pow(1.059, the_harm) => target_freq;
        // print
        <<< "new interval:", the_harm >>>;
    }
}

