// by Drummond Base, October 2020
// First define some global durations
1 :: second => dur whole; // (1) Defines whole, half, and quarter note durations.
whole / 2 => dur half;
whole / 4 => dur quarter;

// Kick drum function
fun void kick() {         // (2) Function to play kick drum.
    SndBuf kick => dac;
    me.dir()+"/audio/kick_01.wav" => kick.read;
    // only play every whole note
    while (true) {
        whole => now;
        0 => kick.pos;
    }
}

// Snare drum function
fun void snare() {        // (3) Function to play snare drum.
    SndBuf snare => dac;
    me.dir()+"/audio/snare_01.wav" => snare.read;
    // play with half note tempo
    while (true) {
        half => now;
        0 => snare.pos;
    }
}

// Hi hat drum function
fun void hihat() {        // (4) Function to play hi-hat.
    SndBuf hihat => dac;
    me.dir()+"/audio/hihat_01.wav" => hihat.read;
    0.2 => hihat.gain;
    // play every quarter note
    while (true) {
        quarter => now;
        0 => hihat.pos;
    }
}

// Main program to spork our individual drum functions
// start off with kick drum for two measures
spork ~ kick();         // (5) Sporking kick function starts it playing
2*whole => now;

// then add in hi hat after two measures
spork ~ hihat();        // (6) Sporks hi-hat after a time
2*whole => now;

// add snare, but on off beats (quarter delayed start)
quarter => now;
spork ~ snare();        // (7) Sporks snare starting on off beat

// let it run for four more measures
4*whole => now;         // (8) Lets it all run for four more measures

// Listing 8.3 Controlling different aspects of a single global object using concurrency

// sound chain
ModalBar modal => NRev reverb => dac;  // (1) Modal bar through reverb to dac

// set reverb mix
.1 => reverb.mix;

// modal bar parameters
7 => modal.preset;
.9 => modal.strikePosition;

// spork detune() as a child shred
// note: must do this before entering into infinite loop below!
spork ~ detune();                     // (2) Sporks a function called detune()

// infinite time loop
while( true )
{
    // first note! then wait
    1 => modal.strike;               // (3) Play notes (strike bar).
    250::ms => now;
    .7 => modal.strike; // another note! then wait
    250::ms => now;
    .9 => modal.strike; // one more note! then wait
    250::ms => now;
    repeat( 4 ) // now play four quick notes
    {
        // note! and wait
        .5 => modal.strike;
        62.5::ms => now;
    }
}

// function to vary tuning over time
fun void detune()                 // (4) detune function definition.
{
    while( true ) // infinite loop
    {
        // update frequency sinusoidally
        84 + Math.sin(now/second*.25*Math.PI) * 2 => Std.mtof => modal.freq;
        // advance time (controls update rate)
        5::ms => now;
    }
}

