// karplus + strong plucked string filter
// Ge Wang (gewang@cs.princeton.edu)

// feedforward
Noise imp => OneZero lowpass => dac;
// feedback
lowpass => Delay delay => lowpass;

// our radius
.99999 => float R;
// our delay order
500 => float L;
// set delay
L::samp => delay.delay;
// set dissipation factor
Math.pow( R, L ) => delay.gain;
// place zero
-1 => lowpass.zero;

// fire excitation
1 => imp.gain;
// for one delay round trip
L::samp => now;
// cease fire
0 => imp.gain;

// advance time
(Math.log(.0001) / Math.log(R))::samp => now;

// plucked string filter, different excitation
// Ge Wang (gewang@cs.princeton.edu)

// feedforward
SndBuf buffy => PoleZero block => OneZero lowpass => dac;
// feedback
lowpass => Delay delay => lowpass;

// our radius
.99999 => float R;
// our delay order
250 => float L;
// set delay
L::samp => delay.delay;
// set dissipation factor
Math.pow( R, L ) => delay.gain;
// take out DC and neighborhood
.999 => block.blockZero;
// place zero
-1 => lowpass.zero;

// fire excitation (try other sounds too)
"special:mand1" => buffy.read;

// advance time
(Math.log(.0001) / Math.log(R))::samp => now;

// tuned plucked string filter
// Ge Wang (gewang@cs.princeton.edu)

// feedforward
Noise imp => OneZero lowpass => PoleZero allpass => dac;
// feedback
allpass => Delay delay => lowpass;

// our radius
.99999 => float R;
// finding our (integer) delay order
Std.mtof( 36.5 ) => setFreq => float L;
// set delay
L::samp => delay.delay;
// set dissipation factor
Math.pow( R, L ) => delay.gain;
// place zero
-1 => lowpass.zero;

// fire excitation
1 => imp.gain;
// for one delay round trip
L::samp => now;
// done
0 => imp.gain;

// advance time
(Math.log(.0001) / Math.log(R))::samp => now;

// set (fundamental) freq
fun int setFreq( float freq )
{
    // sample rate
    second / samp => float SR;
    // omega
    2 * pi * freq / SR => float omega;
    // figure total delay needed
    SR / freq - .5 => float D;
    // the integer part
    D $ int => int Di;
    // the fraction
    D - Di => float Df;
    // set allpass using fractional and fundamental
    polePos( Df, omega ) => allpass.allpass;

    // return integer portion
    return Di;
}

// find pole location from delay and omega
fun float polePos( float D, float omega )
{
    // here it is (a la Jaffe & Smith)
    return Math.sin( (1-D) * omega / 2 ) / 
           Math.sin( (1+D) * omega / 2 );
}

// name: room.ck
// desc: Alvin Lucier's "I Am Sitting in a Room"... in ChucK
// author: Nick Shaheed
// date: Fall 2025 ChucKathon

// we need two LiSa objects: one to record the room, 
// and one to play back the feedback loop. These will
// alternate the act of recording and audio playback.
adc => LiSa loop1 => dac;
adc => LiSa loop2 => dac;

// initialize
0.1::minute => dur loopDur => loop1.duration => loop2.duration;

// ramp-on time
200::ms => loop1.recRamp => loop2.recRamp;

// record first iteration of loop, this is where you speak
<<< "Begin recording your monologue..." >>>;
true => loop1.record;

// don't playback audio for the first iteration of the loop
loop1.duration() => now;
// turn off loop1 recording...
false => loop1.record;

// the feedback loop
while( true )
{
    // wtate 1: loop1 will play back audio and loop2 will record
    false => loop2.play => loop1.record;
    true => loop1.play => loop2.record;
    loopDur => now;

    // state 2: loop2 will play back audio and loop1 will record
    false => loop1.play => loop2.record;
    true => loop2.play => loop1.record;
    loopDur => now;
}

// Fairly silly program to synthesize the
// word "chuck" in ChucK.  Perry Cook, Nov. 2007

TwoPole r[3];	// Resonators
Noise n => Envelope ne => r[0] => TwoZero z => Gain gain => dac;
n => r[1] => z; n => r[2] => z; 
Impulse i => Envelope ie => OnePole o => r[0]; o => r[1]; o => r[2];
0.99 => o.pole; 10.0 => o.gain; 1.0 => z.b0; 0.0 => z.b1; -1.0 => z.b2;

// louder
