    1 => ie.keyOff;
    0.1 :: second => now;
    0 => notDone;
}

fun void doCh()  {
    <<< "Ch" >>>;
    0.03=>ne.time;
    1900.0 => r[0].freq; 0.99 => r[0].radius; 1.0 => r[0].gain;
    2700.0 => r[1].freq; 0.99 => r[1].radius; 0.7 => r[1].gain;
    3200.0 => r[2].freq; 0.99 => r[2].radius; 0.8 => r[2].gain;
    0.0 => i.gain;
    0.02 => n.gain;
    1=>ne.keyOn;0.03 :: second => now;
