fun void doKay()  {
    <<< "kK" >>>;
    0.0 => i.gain;
    0.05 :: second => now;
    0.005=>ne.time;
    0.007 => n.gain;
    380.0 => r[0].freq; 0.99 => r[0].radius; 0.7 => r[0].gain;
    1700.0 => r[1].freq; 0.99 => r[1].radius; 1.0 => r[1].gain;
    4500.0 => r[2].freq; 0.99 => r[2].radius; 0.7 => r[2].gain;
    1 => ne.keyOn; 0.005 :: second => now;
    1 => ne.keyOff;0.01=>ne.time; 0.01 :: second => now;
}

fun void doimpulse()  {
    150.0 => float freq;
    <<< "uhh" >>>;
    while (notDone)  {
        1.0 => i.next;
        (1.0 / freq) :: second => now;    
        freq * 0.98 => freq;
    }
}

//--------------------------------------------------------------------
// name: shepard.ck
// desc: continuous shepard-risset tone generator; 
//       ascending but can easily made to descend
//
// author: Ge Wang (https://ccrma.stanford.edu/~ge/)
//   date: spring 2016
//--------------------------------------------------------------------

// mean for normal intensity curve
66 => float MU;
// standard deviation for normal intensity curve
42 => float SIGMA;
// normalize to 1.0 at x==MU
1 / Math.gauss(MU, MU, SIGMA) => float SCALE;
// increment per unit time (use negative for descending)
.004 => float INC;
// unit time (change interval)
1::ms => dur T;

// starting pitches (in MIDI note numbers, octaves apart)
[ 12.0, 24, 36, 48, 60, 72, 84, 96, 108 ] @=> float pitches[];
// number of tones
pitches.size() => int N;
// bank of tones
TriOsc tones[N];
// overall gain
Gain gain => dac; 1.0/N => gain.gain;
// connect to dac
for( int i; i < N; i++ ) { tones[i] => gain; }

// infinite time loop
while( true )
{
    for( int i; i < N; i++ )
    {
        // set frequency from pitch
        pitches[i] => Std.mtof => tones[i].freq;
        // compute loundess for each tone
        Math.gauss( pitches[i], MU, SIGMA ) * SCALE => float intensity;
        // map intensity to amplitude
        intensity*96 => Math.dbtorms => tones[i].gain;
        // increment pitch
        INC +=> pitches[i];
        // wrap (for positive INC)
        if( pitches[i] > 120 ) 108 -=> pitches[i];
        // wrap (for negative INC)
        else if( pitches[i] < 12 ) 108 +=> pitches[i];
    }

    // advance time
    T => now;
}

// name: smb.ck
// desc: a ChucK rendition of the Super Mario Bros.
//       "Ground Theme" by Koji Kondo.
//
// author: program by Wesley Burchell
// date: updated 11/18/2017

// melody
SqrOsc melody => dac;
// harmony
SqrOsc harmony => dac;
// bass
TriOsc bass => Bitcrusher8 bits => Gain bassGain => dac;
// filter and compressor
LPF filt => Dyno crush => Gain g => dac;
// drums
Noise drums => filt;

// model that 8-bit bass
class Bitcrusher8 extends Chugen
{
    fun float tick(float in)
    {
        return ((in * 8 ) $ int) / 8.0;
    }
}

// a few vars
int m, h, b, d;
// The following array shows the order of patterns in the song.
[7,0,1,0,1,2,3,2,4,2,3,2,4,5,6,5,7,0,1,0,1,8,9,8,10,8,9,8,10,5,6,5,7,8,9,8,10] @=> int seq[];

// compressor settings
crush.compress();
0.001 => crush.thresh;
1.0 => crush.slopeBelow;
0.0 => crush.slopeAbove;
1::samp => crush.attackTime;
1::samp => crush.releaseTime;
37.5 => g.gain;
0 => int time1;
0 => int time2;
0 => int pattern;
0.25 => float gain;
1 => bass.gain;
0.0 => melody.gain;
0.0 => harmony.gain;
0.0 => bassGain.gain;
0.0 => drums.gain;

// time loop
while( true )
{
    checkSqrNote( m, melody ) => m;
    checkSqrNote( h, harmony ) => h;
    checkTriNote();
    checkNoiNote();
    playPattern( seq[pattern] );
    // tick
    735::samp => now;
    time1++;
    if( time1 / 3 > 47 )
    {
        0 => time1;
        pattern++;
    }
    if( pattern == seq.size() ) // end of song
    {
        1 => pattern; // go back to the second pattern (1 )
    }
}

//{ Note checks. These test if a note should be played, and if so, they play the note.
fun int checkSqrNote( int amount, SqrOsc sqr )
{
    if( amount == 7 )
    {   
        0.5 * gain => sqr.gain;
    }
    else if( amount == 6 )
    {   
        0.4375 * gain => sqr.gain;
    }
    else if( amount == 5 )
    {   
        0.375 * gain => sqr.gain;
    }
    else if( amount == 4 )
    {   
        0.3125 * gain => sqr.gain;
    }
    else if( amount == 2 )
    {   
        0.25 * gain => sqr.gain;
    }
    else if( amount != 3 && amount != 1 )
    {   
        0.0 => sqr.gain;
    }
    if( amount > 0 )
    {
        1 -=> amount;
    }
    return amount;
}

fun void checkTriNote()
{
    if( b == 8 )
    {   
        0.0 => bass.phase;
        gain => bassGain.gain;
    }
    else if( b < 1 || b > 8 )
    {
        0.0 => bassGain.gain;
    }
    if( b > 0 )
    {
        1 -=> b;
    }
}

fun void checkNoiNote()
{
