for( int i; i < s.size(); i++ )
{
    // patch each voice
    s[i] => chor[i] => dac;

    // sine wave as source signal
    s[i].gain( .2 );
    s[i].freq( Std.mtof(notes[i]) );

    // initializing a light chorus effect
    // (try tweaking these values!)
    chor[i].baseDelay( 10::ms );
    chor[i].modDepth( .4 );
    chor[i].modFreq( 1 );
    chor[i].mix( .2 );
}

// time loop
while( true )
{
    // nothing to do here except advance time
    1::second => now;
}

