// a chugen!
class Fuzz extends Chugen
{
    // p
    1.0/2.0 => float p;
    // intensity
    2 => intensity;

    // single-sample tick function (ChuGen specialty)    
    fun float tick( float in )
    {
        Math.sgn(in) => float sgn;
        return Math.pow(Math.fabs(in), p) * sgn;
    }

