// name: eval-global.ck
// desc: this example uses Machine.eval() to run generated code
//       to update a global variable; this also shows Machine.eval()
//       running the evaluatd code synchronously and immediately
//
// version: requires chuck-1.5.0.5 or higher
//          Machine.eval() was first introduced in 1.5.0.0;
//          the operation semantics was changed in 1.5.0.5 for
//          Machine eval to run immediately, and automatically
//          yielding the current shred to give the eval'ed code
//          a chance to run -- all this without advancing time
//
// uncomment this to print out info about Machine:
// Machine.help();
//
// date: Summer 2023

// a shared value among shreds
global int g_value;

// initial value
100 => g_value;

// code str
"global int g_value; g_value++;" => string code;

// do this a couple of times
repeat( 3 )
{
    // this shows the execution order of Machine.eval() within
    // a single line of code -- Machine.eval() runs the new code
    // immediately (and synchronously) before continuing the
    // current shred (even if it's in the middle of a statement)
    // as shown below 
    cherr <= g_value <= " "
          <= (Machine.eval(code) ? "(eval)" : "(error)") <= " "
          <= g_value <= " "
          <= (Machine.eval(code) ? "(eval)" : "(error)")
          <= IO.nl();
}

// name: eval.ck
// desc: use Machine.eval() to compile and run code from a string;
//       this as enables chuck to generate code to run at run-time;
//       powerful! perilous!
//
// version: requires chuck-1.5.0.5 or higher
//          Machine.eval() was first introduced in 1.5.0.0;
//          the operation semantics was changed in 1.5.0.5 for
//          Machine eval to run immediately, and automatically
//          yielding the current shred to give the eval'ed code
//          a chance to run -- all this without advancing time
//
// uncomment this to print out info about Machine:
// Machine.help();
//
// date: Spring 2023

// our code to run
"cherr <= \"hello!\" <= IO.newline();" => string codeStr;

// compile the string as code and spork it as a new shred
if( !Machine.eval( codeStr ) ) <<< "error evaluating code!", "" >>>;

// each of these will be evaluated and run as code,
// each on its independent shred; Machine.eval() automatically
// yields the originating "evaluator" shred, giving the evaluated
// code a chance to run without advancing time
Machine.eval( "<<< 1 >>>;" );
<<< "a" >>>;
Machine.eval( "<<< 2 >>>;" );
<<< "b" >>>;
Machine.eval( "<<< 3 >>>;" );
<<< "c" >>>;

// usage examples for a number of Machine functions
// (requires chuck-1.5.1.3 or higher)
//
// see ChucK API Reference on Machine
// https://chuck.stanford.edu/doc/reference/base.html#Machine
//
// or uncomment the next line to print Machine usage
// Machine.help()

// print language version
<<< "chuck version:", Machine.version() >>>;

// keep informed
<<< "\nMachine.eval() example...", "" >>>;

// compile the string as code and spork it as a new shred
// also see eval.ck for more on Machine.eval()
Machine.eval( "repeat(5) { <<< Math.random2f(0,1) >>>; }" );

// keep informed
<<< "\nwaiting for half a second...", "" >>>;

// advance time
.5::second => now;

// keep informed
<<< "\ntrying some shred management...", "" >>>;

// add
Machine.add( me.dir() + "test1.ck:foo" ) => int id;
// yield to give new shred a chance to run
me.yield();

// replace
Machine.replace( id, me.dir() + "test2.ck:bar:5" ) => id;
// yield to give new shred a chance to run
me.yield();

// print current VM status (list of shreds)
Machine.printStatus();
// remove shred
Machine.remove( id );

// keep informed
<<< "\ntrying more Machine functions...", "" >>>;
// print current VM time
Machine.printTimeCheck();
// reset shred IDs to current highest + 1
Machine.resetShredID();
// remove all shreds (including this one!)
Machine.removeAllShreds();
// reset type system and all global variables; remove all shreds
// Machine.clearVM();

// unreachable code
<<< "shouldn't get here" >>>;

// on-the-fly shred management

// this is kind of like using the OTF commands 
//     add / remove / replace etc.
// except this is done from code and also can be timed.
// (this is also a hack for including other files)

// infinite time loop 
while( true )
{
    // the path is relative to where 'chuck' is invoked
    Machine.add( "../basic/moe.ck" ) => int moe;

    // the operation is sample synchronous
    500::ms => now;

    // replace
    Machine.replace( moe, "../basic/wind.ck" ) => int wind;

    500::ms => now;

    // remove
    Machine.remove( wind );
}

