//-----------------------------------------------------------
// (requires: chuck-1.5.5.8 or higher)
// the general format for overload an operator is as follows:
//-----------------------------------------------------------
// let's say we define a custom class...
public class Foo { int num; }

// persistent operator overloading (transcends file contexts)
// NOTE the use of 'public' instead of 'fun' -- it's fun for all!
public Foo @operator =^( Foo lhs, Foo rhs )
{ /* do stuff for Foo =^ Foo */ return rhs; }

// LOCAL binary operator overload for '=>' (local to this context)
fun Foo @operator =>( Foo lhs, Foo rhs )
{ /* do stuff for Foo => Foo */ return rhs; }

// define binary operator overload for '+'
fun Foo @operator +( Foo lhs, Foo rhs )
{ Foo retval; lhs.num + rhs.num => retval.num; return retval; }

// define binary operator overload for '*'
fun Foo @operator *( Foo lhs, Foo rhs )
{ Foo retval; lhs.num * rhs.num => retval.num; return retval; }

// define unary operator overload for '~'
// NOTE: '!' is no longer overloadable as of v1.5.5.8,
// in order to support conditional checks, e.g., if(!obj)
fun int @operator ~( Foo foo )
{ return !foo.num; }

// define postfix operator overload for '++'
fun Foo @operator ( Foo foo ) ++
{ foo.num++; return foo; }

//-----------------------------------------------------------
// using the new overloaded operators
//-----------------------------------------------------------
// create 2 Foos
Foo a, b; 1 => a.num; 2 => b.num;
// operator in action (follows default ck operator precedence)
a + b * b + a @=> Foo c;
// post ++ on c
c++;
// should print 7
<<< c.num >>>;

// 1) example of overloading on objects that return primitives
// 2) simultaneous overloading of pre/post for ++
// 3) example of execution of pre/post increment (same order)
//
// requires: chuck-1.5.5.8 or higher

public class Foo
{ 0 => int n; }

// unary pre overloading
// NOTE: '!' is no longer overloadable as of v1.5.5.8,
// in order to support conditional checks, e.g., if(!obj)
fun int @operator ~(Foo foo)
{
    return !foo.n;
}

// unary pre overloading
fun int @operator ++(Foo foo)
{
    return ++foo.n;
}

// unary postfix overloading
fun int @operator (Foo foo)++
{
    return foo.n++;
}

// make foo
Foo a;
// should print: 1 1 2 2 2 3
<<< ~a, ++a, ++a, a.n, a++, a.n >>>;

// global operator overloading using the 'public' keyword
// overloading an operator in one context, and using it in another
//
// requires chuck-1.5.5.8 or higher

// a custom class
public class Foo
{ 5 => int n; }

// binary operator overloading
// NOTE the use of 'public' keyword
public int @operator +(Foo lhs, Foo rhs)
{
    return lhs.n + rhs.n;
}

// unary prefix overloading
// NOTE: '!' is no longer overloadable as of v1.5.5.8,
// in order to support conditional checks, e.g., if(!obj)
public int @operator ~(Foo foo)
{
    return !foo.n;
}

// unary postfix overloading
public int @operator (Foo foo) ++
{
