//--------------------------------------|
// Dyno demo 2: "Compressor? I didn't even touch 'er!"
// Takes a silly little plucked string demo and runs it through a 
// compressor to enhance sustain. (Ostensibly.) Note that there 
// are many other (better) reasons to use compressors.
//
// authors: Matt Hoffman (mdhoffma at cs.princeton.edu)
//--------------------------------------|

// plucked string, dynamics processor, reverb, dac.
StifKarp m => Dyno d => JCRev r => dac;

// set reverb params
0.75 => r.gain;
0.01 => r.mix;

// set dyno to default compress mode
d.compress();
// set release time to be quite long to enhance sustain
2000::ms => d.releaseTime;
// set threshold to be a bit lower for more pronounced effect.
0.2 => d.thresh;
// set slope (in dB) above the threshold to 1/3 of what it would naturally be
0.33 => d.slopeAbove;
// compensate for the gain reduction
2 => d.gain;

// set plucked string params
0.1 => m.pickupPosition;
0.0 => m.sustain;
0.0 => m.stretch;

// go
while(true)
{
	// play a random note
	Std.mtof( Math.random2(60, 90) ) => m.freq;

    // twice
    repeat( 2 )
    {
        // say whether this pluck is compressed or not
        if(d.op() < 0)
            <<< "uncompressed" >>>;
        else
            <<< "compressed" >>>;

        0.5 => m.pluck;
        2000::ms => now;

        // make the next note compressed if this one wasn't, or vice versa
        -d.op() => d.op;
    }
}

//--------------------------------------|
// Dyno demo 3: "Ducker? She didn't even throw a punch!"
// Shows how to make one sound fade out when another comes up. This is 
// probably more often used by radio DJs than electronic musicians, but
// what the hey.
//
// authors: Matt Hoffman (mdhoffma at cs.princeton.edu)
//--------------------------------------|

// A kick drum that will get quieter when the SinOsc swells.
SndBuf buf => Gain g1 => Dyno dy => JCRev r => dac;
me.sourceDir() + "/../data/kick.wav" => buf.read;
.05 => r.mix;

// A SinOsc that, when its volume swells, will make the kick drum get quieter.
SinOsc s => Gain g2 => r;
220 => s.freq;

// Make dy go into ducker mode
dy.duck();

// spork the shred that makes the kick kick.
spork ~ playKick();

// th is the phase of the low-freq sine that modulates the SinOsc's gain
0 => float th;
// make the SinOsc a bit less annoying
0.5 => g2.gain;

// loop
while( true )
{
	// modulate the SinOsc's gain
	Math.sin(th) + 1.0 => s.gain;
	// send the SinOsc's last sample to dy (manually. yes, this is a pain.)
	s.last() => dy.sideInput;
	// advance the modulating sine's phase a tiny bit
	th + 0.00003 => th;
	// advance time by one sample.
	1::samp => now;
}

// retriggers the kick drum over and over and over and over and over.
fun void playKick()
{
	while(true)
    {
		0 => buf.pos;
		500::ms => now;
	}
}

//--------------------------------------|
// Dyno demo 1: "Limiter? I hardly know 'er!"
// Takes otf_07.ck, cranks the gain up obscenely high, then limits 
// it so it won't clip. 
//
// authors: Matt Hoffman (mdhoffma at cs.princeton.edu)
//          Ge Wang (gewang at cs.princeton.edu)
//          Perry Cook (prc at cs.princeton.edu)
//--------------------------------------|

// this synchronizes to period
.5::second => dur T;
T - (now % T) => now;

// construct the patch
SndBuf buf => Gain g => Dyno dy => JCRev r => dac;
me.sourceDir() + "/../data/kick.wav" => buf.read;
.01 => r.mix;

// make gain way too high, i.e. force clipping
100 => g.gain;
// turn on limiter functionality
dy.limit();
// compensate for the limiter's gain reduction
5 => dy.gain;
// uncomment this to turn off the limiter. note that just because clipping 
// sounds cool here doesn't mean it will in your patch.
// -1 => dy.op;

// where we actually want to start
25 => int where;

// time loop
while( true )
{
    Math.random2f(.8,.9) => buf.gain;

    // note: Math.randomf() returns value between 0 and 1
    if( Math.randomf() > .75 )
    {
        0 => int i;
        while( i < 8 )
        {
            i / 8.0 => buf.gain;
            where => buf.pos;
            (1.0/8.0)::T => now;
            i++;
        }

        while( i > 0 )
        {
            i / 8.0 => buf.gain;
            where => buf.pos;
            (1.0/8.0)::T => now;
            i--;
        }
    }
    else
    {
        .9 => buf.gain;
        where => buf.pos;
        .25::T => now;
        .3 => buf.gain;
        where => buf.pos;
        .25::T => now;
        .3 => buf.gain;
        where => buf.pos;
        .25::T => now;

        .9 => buf.gain;
        where => buf.pos;
        .25::T => now;
        .3 => buf.gain;
        where => buf.pos;
        .25::T => now;
        .3 => buf.gain;
        where => buf.pos;
        .25::T => now;

        .9 => buf.gain;
        where => buf.pos;
        .25::T => now;
        .3 => buf.gain;
        where => buf.pos;
        .25::T => now;
    }
}

// gen10 sinusoidal lookup table
// ported to ChucK from rtcmix by dan trueman
// see luke's page: http://www.music.columbia.edu/cmix/makegens.html#05

Phasor drive => Gen10 g10 => dac;

// can also lookup table values directly:
//     g10.lookup(index);
//     with index:[0,1]

// load up the coeffs; amplitudes for successive partials
g10.coefs( [1., 0.5, 0.3, 0.2] );

// set frequency for reading through table
drive.freq(440.);

// infinite time loop
while (true)
{
    // advance time
    500::ms => now;
    // nothing needed to do, so lets look
    // up some random parts of the table!
    <<< g10.lookup( Math.random2f(0,1) ) >>>;
}

// gen17 chebyshev lookup table
//
// ported to ChucK from rtcmix by dan trueman
// see luke's page: http://www.music.columbia.edu/cmix/makegens.html#06
//
// like gen10, this is a series of weightings for successive partials
//   also http://www.music.columbia.edu/cmc/Rtcmix/docs/scorefile/gen17.html
//   and http://www.music.columbia.edu/cmc/Rtcmix/docs/scorefile/maketable.html (scroll down)
//   for nice documentation of this gen
// see also: http://math.fullerton.edu/mathews/n2003/ChebyshevPolyMod.html
// for info about chebyshev polynomials in general
//
// the main feature to be aware of is that these functions are primarily
// useful for waveshaping, so in this case we drive it with a 
// SinOsc instead of a Phasor. see, for example:
//   http://crca.ucsd.edu/~msp/techniques/v0.08/book-html/node74.html
//   http://en.wikipedia.org/wiki/Distortion_synthesis

// the patch
SinOsc drive => Gen17 g17 => dac;

// load up the coeffs
[1., 0.5, 0.25, 0.125, 0.06, 0.03, 0.015] => g17.coefs;
// some examples to try
// [1., 0.5, 0.3, 0.2] => g17.coefs;
// [1., 0.5, 0.25, 0.125, 0.06, 0.03, 0.015] => g17.coefs;
// [1., 0.] @=> g17.coefs; // a simple one

// make it quiet
0.1 => g17.gain;

// set frequency for reading through table
drive.freq( 440 );
// sounds better not going to extremes
drive.gain( 0.99 ); 

// create an envelope to scan through the table values
// so we can look at them as well as hear them
Envelope e => blackhole;
e.duration( 10000::ms );
0. => e.value;
e.keyOn();

// loop
while (true)
{
    // print
    <<< e.value(), g17.lookup(e.value()) >>>;

    // stop when envelope reaches 1
    if( e.value() == 1. ) break;

    // advance time
    10::ms => now;
}

// gen5: exponential line segment table generator
// probably superceded by CurveTable
// ported to ChucK from rtcmix by dan trueman
// see luke's page: http://www.music.columbia.edu/cmix/makegens.html#02

// make one, no sound here
Gen5 g5;

// set up the values [0,1] and distances in the table
// first arg is initial value 
// followed by pairs indicating distance (total distance = 1)
// and destination value for exponential segments
// NOTE: real minimum value is 0.000001

// the following will create a triangle, with a peak at 1 halfway
