[0., 0.5, 1., 0.5, 0.] => g5.coefs;

// create an envelope to scan through the table values
// creates a continuous input from 0 -> 1 over 10 seconds
Envelope e => blackhole;
e.duration( 10000::ms );
0. => e.value;
e.keyOn();

// loop
while (true)
{
    // print
    <<<e.value(), g5.lookup(e.value())>>>;

    // end
    if( e.value() == 1. ) break;

    // advance time
    10::ms => now;
}

