loopme.record(1);
// wait for a second
1000::ms => now;
// stop recording input
loopme.record(0);

// set track mode to 1, where the input chooses playback position
// note that you can still record this input
1 => loopme.track;
// disconnect sinosc as input
s =< loopme;
// use envelope to control playback position
Step i => Envelope e => loopme;
// set step hold value
1 => i.next;

// play it forward twice speed
500::ms => e.duration;
// open envelope
e.keyOn();
// play
loopme.play(1);
// advance time
500::ms => now;

// now backwards half speed
2000::ms => e.duration;
// close envelope
e.keyOff();
// advance time
2000::ms => now;
// stop playing
loopme.play(0);

// bye bye

