// interp
fun void interp( float slew, dur RATE )
{
    while( true )
    {
        // interp grain position
        (GRAIN_POSITION_GOAL - GRAIN_POSITION)*slew + GRAIN_POSITION => GRAIN_POSITION;
        // interp rate
        RATE => now;
    }
}

