0.0 => f.controlTwo;
<<< f.controlOne(), f.controlTwo() >>>;
arpeg();

0.0 => f.controlOne;  1.0 => f.controlTwo;
<<< f.controlOne(), f.controlTwo() >>>;
arpeg();

//  Now play a proper French Horn solo
0.5 => f.controlOne; 0.8 => f.controlTwo;

// PBDSL:  Perry's Bizarre Demo Score Language //
// Integer part is MIDI note#
// Fractional part is duration
// If only fractional, then it's a rest duration
// Negative cause slur or hold (no notOn rearticulation)
// if MIDI note illegal (>127) then it's vibrato 
[60.2,0.1,65.2,0.05,67.2,0.05,68.7,-69.3,0.1,
 60.2,0.05,65.25,67.25,68.7,-69.3,0.1,
 60.2,65.2,67.2,68.4,69.4,71.25,72.2,74.2,72.2,69.2,67.2,65.3,60.3,57.3,53.4,0.2,48.4,0.4,41.9,600.0,-41.9,1] @=> float notes[];

0.0 => float lastNote;
for (int i; i < notes.cap()-1; i++) {
    Std.abs(Std.ftoi(notes[i])) => int note;
    if (Std.fabs(notes[i]) < 1.0) {
        Std.fabs(notes[i])::second => now;
    }
    else if (notes[i] > 128.0) { // illegal note# = vibrato amt * 10000
        notes[i]/10000.0 => f.lfoDepth;
        <<< "Vibrato!!", f.lfoDepth() >>>;
    }
    else {
        Std.mtof(note) => f.freq;
        if (notes[i] > 0.0) {
            <<< "New Note:", note >>>;
            1 => f.noteOn;
        }
        0.8*(Std.fabs(notes[i])-note)::second => now;
        if (notes[i+1] < 128 & notes[i+1] > 0.0) {
            1 => f.noteOff;
        }
        else <<< "Slur!", "or Hold" >>> ;
        0.2*(Std.fabs(notes[i])-note)::second => now;
    }
}

// let ring...
2*second => now;

fun void arpeg() {
    Std.mtof(48) => f.freq;
    1 => f.noteOn; second => now; 1 => f.noteOff; 0.2*second => now;
    Std.mtof(52) => f.freq;
    1 => f.noteOn; second => now; 1 => f.noteOff; 0.2*second => now;
    Std.mtof(55) => f.freq;
    1 => f.noteOn; second => now; 1 => f.noteOff; 0.2*second => now;
    Std.mtof(60) => f.freq;
    1 => f.noteOn; second => now; 1 => f.noteOff; 0.2*second => now;
}

// name: hevymetl-algo3.ck
// desc: demo of STK FM HevyMetl (Algorithm 3)
// 
// name: Perry R. Cook
// date: June 2021, for REPAIRATHON 2021

// patch
HevyMetl h => NRev r => dac;
// reverb mix
0.05 => r.mix;
// set delay
h => Delay d => d => r; 
// quarter note length
0.25::second => dur T;
// delay
4*T => d.max => d.delay;
// feedback gain
0.25 => d.gain;

// time loop
while( true )
{
    // LFO depth
    0.0 => h.lfoDepth;

    // play notes
    playNote( 66,2*T );
    playNote( 66,T );
    playNote( 66,T );
    playNote( 67,T );
    playNote( 67,3*T );
    playNote( 64,T );

    // from time to time...
    if( maybe*maybe ) playNote(64+2*Math.random2(0,5),2*T);
    else playNote(64,2*T);

    playNote(66,5*T);

    riff();
}

fun void playNote( int note, dur dure )
{
    Std.mtof(note) => h.freq;
    1 => h.noteOn; 
    0.9*(dure) => now;
    1 => h.noteOff;
    0.1*(dure) => now;
}

fun void riff()
{
    [74,69,66,72,67,62,71,67,62,69] @=> int notes[];
    [1,1,1,2,1,1,2,1,1,5] @=> int durs[];
    for (int i; i < notes.cap(); i++)
    {
        Std.mtof(notes[i]) => h.freq;
        1 => h.noteOn;
        if (i == notes.cap()-1) 0.3 => h.lfoDepth;
        durs[i]*T => now;
    }
    1 => h.noteOff;
}

//-----------------------------------------------------------------------------
// name: hevymetl-dance-now.ck
// desc: riff from "Everybody Dance Now"
//       created using FM Synthesis, for "Everybody SLOrk Now!"
//
// author: Ge Wang (https://ccrma.stanford.edu/~ge/)
// date: Spring 2022
//
// original: inspired by "Gonna Make You Sweat (Everybody Dance Now)"
//           C+C Music Factory
//
// code notes:
//   * OFFSET: pitch of third note in power chord (try 0, -12, 12)
//   * DO_ECHO: set to 0 for clean chords; 1 for feedback echo
//   * USE_ENV: controls the attack; set to 0 for hevymetl attack
//-----------------------------------------------------------------------------
// note: want to learn more about HevyMetl? uncomment following line:
// HevyMetl.help();
//-----------------------------------------------------------------------------

// quarter note duration
0.2615::second => dur R;
// detune ("Everybody Dance Now" in Bb + somewhat sharper)
.3 => float TUNE;
// pitch of third note in power chord (try 0, -12, 12)
0  => int OFFSET;
// controls the attack; set to 0 for hevymetl attack
1 => int USE_ENV;
// set to 0 for clean chords; 1 for feedback echo
1 => int DO_ECHO;

// patch
HevyMetl h[3];
// high pass (for echoes)
HPF hpf[3];
// reverb
NRev r => dac; .5 => dac.gain;
// reverb mix
0.0 => r.mix;
// feedback delay
Delay d => r;
d => Gain feedback => d;
// delay
R => d.max => d.delay;
// delay gain
0.4 => d.gain;
// feedback
0.15 => feedback.gain;

// FM operator envelope indices
[31,31,31,31] @=> int attacks[]; // [18,14,15,15] from patch
[31,31,31,31] @=> int decays[];  // [31,31,26,31] from patch
[15,15,15,10] @=> int sustains[]; // [15,15,13,15] from patch
[31,31,31,31] @=> int releases[]; // [8,8,8,8] from patch

// connect
for( int i; i < 3; i++ )
{
    h[i] => r;
    // set delay
    h[i] => hpf[i] => d;
    // set high pass
    600 => hpf[i].freq;

    // LFO depth
    0.0 => h[i].lfoDepth;

    if( USE_ENV)
    {
        // ops
        for( 0=>int op; op < 4; op++ )
        {
            h[i].opADSR( op,
            h[i].getFMTableTime(attacks[op]),
            h[i].getFMTableTime(decays[op]),
            h[i].getFMTableSusLevel(sustains[op]),
            h[i].getFMTableTime(releases[op]) );
        }
    }
}

// time loop
while( true )
{
    // echo gain
    DO_ECHO * .5 => d.gain;

    // do it
    playChord( 46, 53, 46+OFFSET, .8, R );
    2*R => now;
    playChord( 46, 53, 46+OFFSET, .8, R );
    1*R => now;
    playChord( 41, 48, 41+OFFSET, 1.0, R*.8 ); .2*R => now;
    R/2+0*R => now;
    playChord( 44, 51, 44+OFFSET, .9, R*.8 ); .2*R => now;
    R/2+0*R => now;
}

fun void playChord( int a, int b, int c, float vel, dur D )
{
    // set the pitches
    Std.mtof(a+TUNE) => h[0].freq;
    Std.mtof(b+TUNE) => h[1].freq;
    Std.mtof(c+TUNE) => h[2].freq;

    // note on
    for( 0 => int i; i < 3; i++ )
    { vel => h[i].noteOn; }
    // sound
    0.85*(D) => now;

    // note off
    for( 0 => int i; i < 3; i++ )
    { 1 => h[i].noteOff; }
    // let ring
    0.15*(D) => now;
}

// name: hevymetl-trumpet-algo3.ck
// desc: demo of how to turn HevyMetl (Algorithm 3) into an FM Trumpet!!
//       now you can transcribe (somewhat) directly from a TX81 Patch!!!
//
// author: Perry R. Cook
// date: June 2021, for REPAIRATHON 2021
